def match_request(self) -> None:
    """Apply routing to the current request, storing either the matched
    endpoint and args, or a routing exception.
    """
    try:
        result = self.url_adapter.match(return_rule=True)  # type: ignore[union-attr]
    except HTTPException as e:
        self._request.routing_exception = e  # type: ignore[union-attr]
    else:
        self._request.url_rule, self._request.view_args = result  # type: ignore[union-attr]

def preprocess_request(self, ctx: AppContext) -> ft.ResponseReturnValue | None:
    """Called before the request is dispatched. Calls
    :attr:`url_value_preprocessors` registered with the app and the
    current blueprint (if any). Then calls :attr:`before_request_funcs`
    registered with the app and the blueprint.

    If any :meth:`before_request` handler returns a non-None value, the
    value is handled as if it was the return value from the view, and
    further request handling is stopped.
    """
    req = ctx.request
    names = (None, *reversed(req.blueprints))

    for name in names:
        if name in self.url_value_preprocessors:
            for url_func in self.url_value_preprocessors[name]:
                url_func(req.endpoint, req.view_args)

    for name in names:
        if name in self.before_request_funcs:
            for before_func in self.before_request_funcs[name]:
                rv = self.ensure_sync(before_func)()

                if rv is not None:
                    return rv  # type: ignore[no-any-return]

    return None

def process_response(self, ctx: AppContext, response: Response) -> Response:
    """Can be overridden in order to modify the response object
    before it's sent to the WSGI server.  By default this will
    call all the :meth:`after_request` decorated functions.

    .. versionchanged:: 0.5
       As of Flask 0.5 the functions registered for after request
       execution are called in reverse order of registration.

    :param response: a :attr:`response_class` object.
    :return: a new response object or the same, has to be an
             instance of :attr:`response_class`.
    """
    for func in ctx._after_request_functions:
        response = self.ensure_sync(func)(response)

    for name in chain(ctx.request.blueprints, (None,)):
        if name in self.after_request_funcs:
            for func in reversed(self.after_request_funcs[name]):
                response = self.ensure_sync(func)(response)

    if not self.session_interface.is_null_session(ctx._get_session()):
        self.session_interface.save_session(self, ctx._get_session(), response)

    return response

def _find_error_handler(
    self, e: Exception, blueprints: list[str]
) -> ft.ErrorHandlerCallable | None:
    """Return a registered error handler for an exception in this order:
    blueprint handler for a specific code, app handler for a specific code,
    blueprint handler for an exception class, app handler for an exception
    class, or ``None`` if a suitable handler is not found.
    """
    exc_class, code = self._get_exc_class_and_code(type(e))
    names = (*blueprints, None)

    for c in (code, None) if code is not None else (None,):
        for name in names:
            handler_map = self.error_handler_spec[name][c]

            if not handler_map:
                continue

            for cls in exc_class.__mro__:
                handler = handler_map.get(cls)

                if handler is not None:
                    return handler
    return None

@setupmethod
def app_errorhandler(
    self, code: type[Exception] | int
) -> t.Callable[[T_error_handler], T_error_handler]:
    """Like :meth:`errorhandler`, but for every request, not only those handled by
    the blueprint. Equivalent to :meth:`.Flask.errorhandler`.
    """

    def decorator(f: T_error_handler) -> T_error_handler:
        def from_blueprint(state: BlueprintSetupState) -> None:
            state.app.errorhandler(code)(f)

        self.record_once(from_blueprint)
        return f

    return decorator

@setupmethod
def before_app_request(self, f: T_before_request) -> T_before_request:
    """Like :meth:`before_request`, but before every request, not only those handled
    by the blueprint. Equivalent to :meth:`.Flask.before_request`.
    """
    self.record_once(
        lambda s: s.app.before_request_funcs.setdefault(None, []).append(f)
    )
    return f

@setupmethod
def after_app_request(self, f: T_after_request) -> T_after_request:
    """Like :meth:`after_request`, but after every request, not only those handled
    by the blueprint. Equivalent to :meth:`.Flask.after_request`.
    """
    self.record_once(
        lambda s: s.app.after_request_funcs.setdefault(None, []).append(f)
    )
    return f

def after_this_request(
    f: ft.AfterRequestCallable[t.Any],
) -> ft.AfterRequestCallable[t.Any]:
    """Decorate a function to run after the current request. The behavior is the
    same as :meth:`.Flask.after_request`, except it only applies to the current
    request, rather than every request. Therefore, it must be used within a
    request context, rather than during setup.

    .. code-block:: python

        @app.route("/")
        def index():
            @after_this_request
            def add_header(response):
                response.headers["X-Foo"] = "Parachute"
                return response

            return "Hello, World!"

    .. versionadded:: 0.9
    """
    ctx = _cv_app.get(None)

    if ctx is None or not ctx.has_request:
        raise RuntimeError(
            "'after_this_request' can only be used when a request"
            " context is active, such as in a view function."
        )

    ctx._after_request_functions.append(f)
    return f

@setupmethod
def app_url_value_preprocessor(
    self, f: T_url_value_preprocessor
) -> T_url_value_preprocessor:
    """Like :meth:`url_value_preprocessor`, but for every request, not only those
    handled by the blueprint. Equivalent to :meth:`.Flask.url_value_preprocessor`.
    """
    self.record_once(
        lambda s: s.app.url_value_preprocessors.setdefault(None, []).append(f)
    )
    return f

def on_json_loading_failed(self, e: ValueError | None) -> t.Any:
    try:
        return super().on_json_loading_failed(e)
    except BadRequest as ebr:
        if current_app and current_app.debug:
            raise

        raise BadRequest() from ebr

def decorator(f: T_error_handler) -> T_error_handler:
    def from_blueprint(state: BlueprintSetupState) -> None:
        state.app.errorhandler(code)(f)

    self.record_once(from_blueprint)
    return f

def decorator(f: T_error_handler) -> T_error_handler:
    self.register_error_handler(code_or_exception, f)
    return f

@staticmethod
def _get_exc_class_and_code(
    exc_class_or_code: type[Exception] | int,
) -> tuple[type[Exception], int | None]:
    """Get the exception class being handled. For HTTP status codes
    or ``HTTPException`` subclasses, return both the exception and
    status code.

    :param exc_class_or_code: Any exception class, or an HTTP status
        code as an integer.
    """
    exc_class: type[Exception]

    if isinstance(exc_class_or_code, int):
        try:
            exc_class = default_exceptions[exc_class_or_code]
        except KeyError:
            raise ValueError(
                f"'{exc_class_or_code}' is not a recognized HTTP"
                " error code. Use a subclass of HTTPException with"
                " that code instead."
            ) from None
    else:
        exc_class = exc_class_or_code

    if isinstance(exc_class, Exception):
        raise TypeError(
            f"{exc_class!r} is an instance, not a class. Handlers"
            " can only be registered for Exception classes or HTTP"
            " error codes."
        )

    if not issubclass(exc_class, Exception):
        raise ValueError(
            f"'{exc_class.__name__}' is not a subclass of Exception."
            " Handlers can only be registered for Exception classes"
            " or HTTP error codes."
        )

    if issubclass(exc_class, HTTPException):
        return exc_class, exc_class.code
    else:
        return exc_class, None

def has_level_handler(logger: logging.Logger) -> bool:
    """Check if there is a handler in the logging chain that will handle the
    given logger's :meth:`effective level <~logging.Logger.getEffectiveLevel>`.
    """
    level = logger.getEffectiveLevel()
    current = logger

    while current:
        if any(handler.level <= level for handler in current.handlers):
            return True

        if not current.propagate:
            break

        current = current.parent  # type: ignore

    return False

def view(**kwargs: t.Any) -> ft.ResponseReturnValue:
    self = view.view_class(  # type: ignore[attr-defined]
        *class_args, **class_kwargs
    )
    return current_app.ensure_sync(self.dispatch_request)(**kwargs)  # type: ignore[no-any-return]

def _method_route(
    self,
    method: str,
    rule: str,
    options: dict[str, t.Any],
) -> t.Callable[[T_route], T_route]:
    if "methods" in options:
        raise TypeError("Use the 'route' decorator to use the 'methods' argument.")

    return self.route(rule, methods=[method], **options)

@property
def request(self) -> Request:
    """The request object associated with this context. Accessed through
    :data:`.request`. Only available in request contexts, otherwise raises
    :exc:`RuntimeError`.
    """
    if self._request is None:
        raise RuntimeError("There is no request in this context.")

    return self._request

def __exit__(
    self,
    exc_type: type[BaseException] | None,
    exc_val: BaseException | None,
    exc_tb: TracebackType | None,
) -> bool:
    if exc_val is not None:
        self.errors.append(exc_val)

    return True

@setupmethod
def teardown_app_request(self, f: T_teardown) -> T_teardown:
    """Like :meth:`teardown_request`, but after every request, not only those
    handled by the blueprint. Equivalent to :meth:`.Flask.teardown_request`.
    """
    self.record_once(
        lambda s: s.app.teardown_request_funcs.setdefault(None, []).append(f)
    )
    return f

def merge_hooks(
    request_hooks: _t.HooksType,
    session_hooks: _t.HooksType,
    dict_class: type = OrderedDict,
) -> _t.HooksType:
    """Properly merges both requests and session hooks.

    This is necessary because when request_hooks == {'response': []}, the
    merge breaks Session hooks entirely.
    """
    if session_hooks is None or session_hooks.get("response") == []:
        return request_hooks

    if request_hooks is None or request_hooks.get("response") == []:
        return session_hooks

    return merge_setting(request_hooks, session_hooks, dict_class)

def __getitem__(self, key: str) -> _VT | None:  # type: ignore[override]
    # We allow fall-through here, so values default to None

    return self.__dict__.get(key, None)

def __setstate__(self, state: dict[str, Any]) -> None:
    for attr, value in state.items():
        setattr(self, attr, value)

def set(
    self, name: str, value: str | Morsel[dict[str, str]] | None, **kwargs: Any
) -> Cookie | None:
    """Dict-like set() that also supports optional domain and path args in
    order to resolve naming collisions from using one cookie jar over
    multiple domains.
    """
    # support client code that unsets cookies by assignment of a None value:
    if value is None:
        remove_cookie_by_name(
            self, name, domain=kwargs.get("domain"), path=kwargs.get("path")
        )
        return

    if isinstance(value, Morsel):
        c = morsel_to_cookie(value)
    else:
        c = create_cookie(name, value, **kwargs)
    self.set_cookie(c)
    return c

def _find_no_duplicates(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str:
    """Both ``__get_item__`` and ``get`` call this function: it's never
    used elsewhere in Requests.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :raises KeyError: if cookie is not found
    :raises CookieConflictError: if there are multiple cookies
        that match name and optionally domain and path
    :return: cookie.value
    """
    toReturn = None
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    if toReturn is not None:
                        # if there are multiple cookies that meet passed in criteria
                        raise CookieConflictError(
                            f"There are multiple cookies with name, {name!r}"
                        )
                    # we will eventually return this as long as no cookie conflict
                    toReturn = cookie.value

    if toReturn is not None:
        return toReturn
    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def default_headers() -> CaseInsensitiveDict[str]:
    """
    :rtype: requests.structures.CaseInsensitiveDict
    """
    return CaseInsensitiveDict(
        {
            "User-Agent": default_user_agent(),
            "Accept-Encoding": DEFAULT_ACCEPT_ENCODING,
            "Accept": "*/*",
            "Connection": "keep-alive",
        }
    )

def get_dict(
    self, domain: str | None = None, path: str | None = None
) -> dict[str, str | None]:
    """Takes as an argument an optional domain and path and returns a plain
    old Python dict of name-value pairs of cookies that meet the
    requirements.

    :rtype: dict
    """
    dictionary: dict[str, str | None] = {}
    for cookie in iter(self):
        if (domain is None or cookie.domain == domain) and (
            path is None or cookie.path == path
        ):
            dictionary[cookie.name] = cookie.value
    return dictionary

def cookiejar_from_dict(
    cookie_dict: dict[str, str] | None,
    cookiejar: CookieJar | None = None,
    overwrite: bool = True,
) -> CookieJar:
    """Returns a CookieJar from a key/value dictionary.

    :param cookie_dict: Dict of key/values to insert into CookieJar.
    :param cookiejar: (optional) A cookiejar to add the cookies to.
    :param overwrite: (optional) If False, will not replace cookies
        already in the jar with new ones.
    :rtype: CookieJar
    """
    if cookiejar is None:
        cookiejar = RequestsCookieJar()

    if cookie_dict is not None:
        names_from_jar = [cookie.name for cookie in cookiejar]
        for name in cookie_dict:
            if overwrite or (name not in names_from_jar):
                cookiejar.set_cookie(create_cookie(name, cookie_dict[name]))

    return cookiejar

def _find(
    self, name: str, domain: str | None = None, path: str | None = None
) -> str | None:
    """Requests uses this method internally to get cookie values.

    If there are conflicting cookies, _find arbitrarily chooses one.
    See _find_no_duplicates if you want an exception thrown if there are
    conflicting cookies.

    :param name: a string containing name of cookie
    :param domain: (optional) string containing domain of cookie
    :param path: (optional) string containing path of cookie
    :return: cookie.value
    """
    for cookie in iter(self):
        if cookie.name == name:
            if domain is None or cookie.domain == domain:
                if path is None or cookie.path == path:
                    return cookie.value

    raise KeyError(f"name={name!r}, domain={domain!r}, path={path!r}")

def __getstate__(self) -> dict[str, Any]:
    state = {attr: getattr(self, attr, None) for attr in self.__attrs__}
    return state

def __init__(
    self,
    data: Mapping[str, _VT] | Iterable[tuple[str, _VT]] | None = None,
    **kwargs: _VT,
) -> None:
    self._store = OrderedDict()
    if data is None:
        data = {}
    self.update(data, **kwargs)

def __setstate__(self, state: dict[str, Any]) -> None:
    """Unlike a normal CookieJar, this class is pickleable."""
    self.__dict__.update(state)
    if "_cookies_lock" not in self.__dict__:
        self._cookies_lock = threading.RLock()

def __setstate__(self, state: dict[str, Any]) -> None:
    # Can't handle by adding 'proxy_manager' to self.__attrs__ because
    # self.poolmanager uses a lambda function, which isn't pickleable.
    self.proxy_manager = {}
    self.config = {}

    for attr, value in state.items():
        setattr(self, attr, value)

    self.init_poolmanager(
        self._pool_connections, self._pool_maxsize, block=self._pool_block
    )

@contextlib.contextmanager
def set_environ(env_name: str, value: str | None) -> Generator[None, None, None]:
    """Set the environment variable 'env_name' to 'value'

    Save previous value, yield, and then restore the previous value stored in
    the environment variable 'env_name'.

    If 'value' is None, do nothing"""
    value_changed = value is not None
    old_value: str | None = None
    if value_changed:
        old_value = os.environ.get(env_name)
        os.environ[env_name] = value
    try:
        yield
    finally:
        if value_changed:
            if old_value is None:
                del os.environ[env_name]
            else:
                os.environ[env_name] = old_value

def __setstate__(self, state: dict[str, Any]) -> None:
    for name, value in state.items():
        setattr(self, name, value)

    # pickled objects do not have .raw
    setattr(self, "_content_consumed", True)
    setattr(self, "raw", None)

def __init__(self, name: Any = None) -> None:
    self.name = name
    super().__init__()

def __contains__(self, name: object) -> bool:
    try:
        return super().__contains__(name)
    except CookieConflictError:
        return True

def update(  # type: ignore[override]
    self, other: CookieJar | SupportsKeysAndGetItem[str, str]
) -> None:
    """Updates this jar with cookies from another CookieJar or dict-like"""
    if isinstance(other, cookielib.CookieJar):
        for cookie in other:
            self.set_cookie(copy.copy(cookie))
    else:
        super().update(other)

def merge_cookies(
    cookiejar: CookieJar, cookies: dict[str, str] | CookieJar | None
) -> CookieJar:
    """Add cookies to cookiejar and returns a merged CookieJar.

    :param cookiejar: CookieJar object to add the cookies to.
    :param cookies: Dictionary or CookieJar object to be added.
    :rtype: CookieJar
    """
    if not isinstance(cookiejar, cookielib.CookieJar):  # runtime guard
        raise ValueError("You can only merge into CookieJar")

    if isinstance(cookies, dict):
        cookiejar = cookiejar_from_dict(cookies, cookiejar=cookiejar, overwrite=False)
    elif isinstance(cookies, cookielib.CookieJar):
        if update_method := getattr(cookiejar, "update", None):
            update_method(cookies)
        else:
            for cookie_in_jar in cookies:
                cookiejar.set_cookie(cookie_in_jar)

    return cookiejar

def __eq__(self, other: object) -> bool:
    if isinstance(other, Mapping):
        other_dict: CaseInsensitiveDict[Any] = CaseInsensitiveDict(other)  # type: ignore[reportUnknownArgumentType]
    else:
        return NotImplemented
    # Compare insensitively
    return dict(self.lower_items()) == dict(other_dict.lower_items())

def convert(
    self, value: t.Any, param: t.Optional["Parameter"], ctx: t.Optional["Context"]
) -> t.Any:
    # Match through normalization and case sensitivity
    # first do token_normalize_func, then lowercase
    # preserve original `value` to produce an accurate message in
    # `self.fail`
    normed_value = value
    normed_choices = {choice: choice for choice in self.choices}

    if ctx is not None and ctx.token_normalize_func is not None:
        normed_value = ctx.token_normalize_func(value)
        normed_choices = {
            ctx.token_normalize_func(normed_choice): original
            for normed_choice, original in normed_choices.items()
        }

    if not self.case_sensitive:
        normed_value = normed_value.casefold()
        normed_choices = {
            normed_choice.casefold(): original
            for normed_choice, original in normed_choices.items()
        }

    if normed_value in normed_choices:
        return normed_choices[normed_value]

    choices_str = ", ".join(map(repr, self.choices))
    self.fail(
        ngettext(
            "{value!r} is not {choice}.",
            "{value!r} is not one of {choices}.",
            len(self.choices),
        ).format(value=value, choice=choices_str, choices=choices_str),
        param,
        ctx,
    )

def __init__(self, choices: t.Sequence[str], case_sensitive: bool = True) -> None:
    self.choices = choices
    self.case_sensitive = case_sensitive

def normalize_opt(opt: str, ctx: t.Optional["Context"]) -> str:
    if ctx is None or ctx.token_normalize_func is None:
        return opt
    prefix, opt = split_opt(opt)
    return f"{prefix}{ctx.token_normalize_func(opt)}"

@property
def human_readable_name(self) -> str:
    if self.metavar is not None:
        return self.metavar
    return self.name.upper()  # type: ignore

@property
def human_readable_name(self) -> str:
    """Returns the human readable name of this parameter.  This is the
    same as the name for options, but the metavar for arguments.
    """
    return self.name  # type: ignore

def _match_long_opt(
    self, opt: str, explicit_value: t.Optional[str], state: ParsingState
) -> None:
    if opt not in self._long_opt:
        from difflib import get_close_matches

        possibilities = get_close_matches(opt, self._long_opt)
        raise NoSuchOption(opt, possibilities=possibilities, ctx=self.ctx)

    option = self._long_opt[opt]
    if option.takes_value:
        # At this point it's safe to modify rargs by injecting the
        # explicit value, because no exception is raised in this
        # branch.  This means that the inserted value will be fully
        # consumed.
        if explicit_value is not None:
            state.rargs.insert(0, explicit_value)

        value = self._get_value_from_state(opt, option, state)

    elif explicit_value is not None:
        raise BadOptionUsage(
            opt, _("Option {name!r} does not take a value.").format(name=opt)
        )

    else:
        value = None

    option.process(value, state)

def _parse_decls(
    self, decls: t.Sequence[str], expose_value: bool
) -> t.Tuple[t.Optional[str], t.List[str], t.List[str]]:
    opts = []
    secondary_opts = []
    name = None
    possible_names = []

    for decl in decls:
        if decl.isidentifier():
            if name is not None:
                raise TypeError(f"Name '{name}' defined twice")
            name = decl
        else:
            split_char = ";" if decl[:1] == "/" else "/"
            if split_char in decl:
                first, second = decl.split(split_char, 1)
                first = first.rstrip()
                if first:
                    possible_names.append(split_opt(first))
                    opts.append(first)
                second = second.lstrip()
                if second:
                    secondary_opts.append(second.lstrip())
                if first == second:
                    raise ValueError(
                        f"Boolean option {decl!r} cannot use the"
                        " same flag for true/false."
                    )
            else:
                possible_names.append(split_opt(decl))
                opts.append(decl)

    if name is None and possible_names:
        possible_names.sort(key=lambda x: -len(x[0]))  # group long options first
        name = possible_names[0][1].replace("-", "_").lower()
        if not name.isidentifier():
            name = None

    if name is None:
        if not expose_value:
            return None, opts, secondary_opts
        raise TypeError(
            f"Could not determine name for option with declarations {decls!r}"
        )

    if not opts and not secondary_opts:
        raise TypeError(
            f"No options defined but a name was passed ({name})."
            " Did you mean to declare an argument instead? Did"
            f" you mean to pass '--{name}'?"
        )

    return name, opts, secondary_opts

def get_editor(self) -> str:
    if self.editor is not None:
        return self.editor
    for key in "VISUAL", "EDITOR":
        rv = os.environ.get(key)
        if rv:
            return rv
    if WIN:
        return "notepad"
    for editor in "sensible-editor", "vim", "nano":
        if which(editor) is not None:
            return editor
    return "vi"

def format_message(self) -> str:
    if not self.possibilities:
        return self.message

    possibility_str = ", ".join(sorted(self.possibilities))
    suggest = ngettext(
        "Did you mean {possibility}?",
        "(Possible options: {possibilities})",
        len(self.possibilities),
    ).format(possibility=possibility_str, possibilities=possibility_str)
    return f"{self.message} {suggest}"

def _start_of_option(ctx: Context, value: str) -> bool:
    """Check if the value looks like the start of an option."""
    if not value:
        return False

    c = value[0]
    return c in ctx._opt_prefixes

def get_text_stdin(
    encoding: t.Optional[str] = None, errors: t.Optional[str] = None
) -> t.TextIO:
    rv = _get_windows_console_stream(sys.stdin, encoding, errors)
    if rv is not None:
        return rv
    return _force_correct_text_reader(sys.stdin, encoding, errors, force_readable=True)

def _format_default(default: t.Any) -> t.Any:
    if isinstance(default, (io.IOBase, LazyFile)) and hasattr(default, "name"):
        return default.name

    return default

def make_metavar(self) -> str:
    if self.metavar is not None:
        return self.metavar

    metavar = self.type.get_metavar(self)

    if metavar is None:
        metavar = self.type.name.upper()

    if self.nargs != 1:
        metavar += "..."

    return metavar

def _get_argv_encoding() -> str:
    import locale

    return locale.getpreferredencoding()

def split_opt(opt: str) -> t.Tuple[str, str]:
    first = opt[:1]
    if first.isalnum():
        return "", opt
    if opt[1:2] == first:
        return opt[:2], opt[2:]
    return first, opt[1:]

def make_metavar(self) -> str:
    if self.metavar is not None:
        return self.metavar
    var = self.type.get_metavar(self)
    if not var:
        var = self.name.upper()  # type: ignore
    if not self.required:
        var = f"[{var}]"
    if self.nargs != 1:
        var += "..."
    return var

@_pause_echo(echo_input)  # type: ignore
def hidden_input(prompt: t.Optional[str] = None) -> str:
    sys.stdout.write(f"{prompt or ''}\n")
    sys.stdout.flush()
    return text_input.readline().rstrip("\r\n")

def consume_value(
    self, ctx: Context, opts: t.Mapping[str, t.Any]
) -> t.Tuple[t.Any, ParameterSource]:
    value = opts.get(self.name)  # type: ignore
    source = ParameterSource.COMMANDLINE

    if value is None:
        value = self.value_from_envvar(ctx)
        source = ParameterSource.ENVIRONMENT

    if value is None:
        value = ctx.lookup_default(self.name)  # type: ignore
        source = ParameterSource.DEFAULT_MAP

    if value is None:
        value = self.get_default(ctx)
        source = ParameterSource.DEFAULT

    return value, source

def get_completion_args(self) -> t.Tuple[t.List[str], str]:
    cwords = split_arg_string(os.environ["COMP_WORDS"])
    cword = int(os.environ["COMP_CWORD"])
    args = cwords[1:cword]

    try:
        incomplete = cwords[cword]
    except IndexError:
        incomplete = ""

    return args, incomplete

def _complete_visible_commands(
    ctx: "Context", incomplete: str
) -> t.Iterator[t.Tuple[str, "Command"]]:
    """List all the subcommands of a group that start with the
    incomplete value and aren't hidden.

    :param ctx: Invocation context for the group.
    :param incomplete: Value being completed. May be empty.
    """
    multi = t.cast(MultiCommand, ctx.command)

    for name in multi.list_commands(ctx):
        if name.startswith(incomplete):
            command = multi.get_command(ctx, name)

            if command is not None and not command.hidden:
                yield name, command

