def include_query_params(self, **kwargs: typing.Any) -> URL:
    params = MultiDict(parse_qsl(self.query, keep_blank_values=True))
    params.update({str(key): str(value) for key, value in kwargs.items()})
    query = urlencode(params.multi_items())
    return self.replace(query=query)

def replace_query_params(self, **kwargs: typing.Any) -> URL:
    query = urlencode([(str(key), str(value)) for key, value in kwargs.items()])
    return self.replace(query=query)

def remove_query_params(self, keys: str | typing.Sequence[str]) -> URL:
    if isinstance(keys, str):
        keys = [keys]
    params = MultiDict(parse_qsl(self.query, keep_blank_values=True))
    for key in keys:
        params.pop(key, None)
    query = urlencode(params.multi_items())
    return self.replace(query=query)

@property
def query_params(self) -> QueryParams:
    if not hasattr(self, "_query_params"):  # pragma: no branch
        self._query_params = QueryParams(self.scope["query_string"])
    return self._query_params

def __init__(
    self,
    *args: ImmutableMultiDict[typing.Any, typing.Any]
    | typing.Mapping[typing.Any, typing.Any]
    | list[tuple[typing.Any, typing.Any]]
    | str
    | bytes,
    **kwargs: typing.Any,
) -> None:
    assert len(args) < 2, "Too many arguments."

    value = args[0] if args else []

    if isinstance(value, str):
        super().__init__(parse_qsl(value, keep_blank_values=True), **kwargs)
    elif isinstance(value, bytes):
        super().__init__(parse_qsl(value.decode("latin-1"), keep_blank_values=True), **kwargs)
    else:
        super().__init__(*args, **kwargs)  # type: ignore[arg-type]
    self._list = [(str(k), str(v)) for k, v in self._list]
    self._dict = {str(k): str(v) for k, v in self._dict.items()}

@property
def query(self) -> str:
    return self.components.query

def replace_params(
    path: str,
    param_convertors: dict[str, Convertor[typing.Any]],
    path_params: dict[str, str],
) -> tuple[str, dict[str, str]]:
    for key, value in list(path_params.items()):
        if "{" + key + "}" in path:
            convertor = param_convertors[key]
            value = convertor.to_string(value)
            path = path.replace("{" + key + "}", value)
            path_params.pop(key)
    return path, path_params

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())

    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)

    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="http")

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    if self.name is not None and name == self.name and "path" in path_params:
        # 'name' matches "<mount_name>".
        path_params["path"] = path_params["path"].lstrip("/")
        path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
        if not remaining_params:
            return URLPath(path=path)
    elif self.name is None or name.startswith(self.name + ":"):
        if self.name is None:
            # No mount name.
            remaining_name = name
        else:
            # 'name' matches "<mount_name>:<child_name>".
            remaining_name = name[len(self.name) + 1 :]
        path_kwarg = path_params.get("path")
        path_params["path"] = ""
        path_prefix, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
        if path_kwarg is not None:
            remaining_params["path"] = path_kwarg
        for route in self.routes or []:
            try:
                url = route.url_path_for(remaining_name, **remaining_params)
                return URLPath(path=path_prefix.rstrip("/") + str(url), protocol=url.protocol)
            except NoMatchFound:
                pass
    raise NoMatchFound(name, path_params)

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    if self.name is not None and name == self.name and "path" in path_params:
        # 'name' matches "<mount_name>".
        path = path_params.pop("path")
        host, remaining_params = replace_params(self.host_format, self.param_convertors, path_params)
        if not remaining_params:
            return URLPath(path=path, host=host)
    elif self.name is None or name.startswith(self.name + ":"):
        if self.name is None:
            # No mount name.
            remaining_name = name
        else:
            # 'name' matches "<mount_name>:<child_name>".
            remaining_name = name[len(self.name) + 1 :]
        host, remaining_params = replace_params(self.host_format, self.param_convertors, path_params)
        for route in self.routes or []:
            try:
                url = route.url_path_for(remaining_name, **remaining_params)
                return URLPath(path=str(url), protocol=url.protocol, host=host)
            except NoMatchFound:
                pass
    raise NoMatchFound(name, path_params)

def replace(self, **kwargs: typing.Any) -> URL:
    if "username" in kwargs or "password" in kwargs or "hostname" in kwargs or "port" in kwargs:
        hostname = kwargs.pop("hostname", None)
        port = kwargs.pop("port", self.port)
        username = kwargs.pop("username", self.username)
        password = kwargs.pop("password", self.password)

        if hostname is None:
            netloc = self.netloc
            _, _, hostname = netloc.rpartition("@")

            if hostname[-1] != "]":
                hostname = hostname.rsplit(":", 1)[0]

        netloc = hostname
        if port is not None:
            netloc += f":{port}"
        if username is not None:
            userpass = username
            if password is not None:
                userpass += f":{password}"
            netloc = f"{userpass}@{netloc}"

        kwargs["netloc"] = netloc

    components = self.components._replace(**kwargs)
    return self.__class__(components.geturl())

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    seen_params = set(path_params.keys())
    expected_params = set(self.param_convertors.keys())

    if name != self.name or seen_params != expected_params:
        raise NoMatchFound(name, path_params)

    path, remaining_params = replace_params(self.path_format, self.param_convertors, path_params)
    assert not remaining_params
    return URLPath(path=path, protocol="websocket")

def __init__(
    self,
    url: str = "",
    scope: Scope | None = None,
    **components: typing.Any,
) -> None:
    if scope is not None:
        assert not url, 'Cannot set both "url" and "scope".'
        assert not components, 'Cannot set both "scope" and "**components".'
        scheme = scope.get("scheme", "http")
        server = scope.get("server", None)
        path = scope["path"]
        query_string = scope.get("query_string", b"")

        host_header = None
        for key, value in scope["headers"]:
            if key == b"host":
                host_header = value.decode("latin-1")
                break

        if host_header is not None:
            url = f"{scheme}://{host_header}{path}"
        elif server is None:
            url = path
        else:
            host, port = server
            default_port = {"http": 80, "https": 443, "ws": 80, "wss": 443}[scheme]
            if port == default_port:
                url = f"{scheme}://{host}{path}"
            else:
                url = f"{scheme}://{host}:{port}{path}"

        if query_string:
            url += "?" + query_string.decode()
    elif components:
        assert not url, 'Cannot set both "url" and "**components".'
        url = URL("").replace(**components).components.geturl()

    self._url = url

@pass_context
def url_for(
    context: dict[str, typing.Any],
    name: str,
    /,
    **path_params: typing.Any,
) -> URL:
    request: Request = context["request"]
    return request.url_for(name, **path_params)

def add_vary_header(self, vary: str) -> None:
    existing = self.get("vary")
    if existing is not None:
        vary = ", ".join([existing, vary])
    self["vary"] = vary

def url_path_for(self, name: str, /, **path_params: typing.Any) -> URLPath:
    for route in self.routes:
        try:
            return route.url_path_for(name, **path_params)
        except NoMatchFound:
            pass
    raise NoMatchFound(name, path_params)

