  if ((s >= 200 && s < 300) || s === 304) {
    return fresh(this.header, this.response.header)
  }

  return false
},

get charset () {
  try {
    const { parameters } = contentType.parse(this.req)
    return parameters.charset || ''
  } catch (e) {
    return ''
  }
},

flushHeaders () {
  this.res.flushHeaders()
}

get length () {
  const len = this.get('Content-Length')
  if (len === '') return
  const parsed = Number.parseInt(len, 10)
  return Number.isNaN(parsed) ? undefined : parsed
},

inspect () {
  if (!this.res) return
  const o = this.toJSON()
  o.body = this.body
  return o
},

get (field) {
  return this.res.getHeader(field)
},

get headerSent () {
  return this.res.headersSent
},

attachment (filename, options) {
  if (filename && !this.has('Content-Type')) {
    this.type = extname(filename)
  }
  this.set('Content-Disposition', contentDisposition(filename, options))
},

toJSON () {
  return only(this, [
    'method',
    'url',
    'header'
  ])
}

function normalizeHeader (field, value) {
  const singletonArray = isSingleValueHeader(field) && Array.isArray(value)
  if (!singletonArray) return [field, value]

  assert(value.length === 1, `${field} must contain exactly one value`)
  return [field, value[0]]
